    /// cooks_distance_vec with empty inputs: should return empty.
    #[test]
    fn bug_hunt_cooks_empty() {
        let cooks = cooks_distance_vec(&[], &[], &[]);
        assert!(cooks.is_empty(), "empty input should produce empty output");
    }

    /// variance_rank_vec with n=0: accessing x_flat[i * p + j] with n=0 means
    /// the loop body never executes. Mean = 0.0/0.0 = NaN. Should not panic.
    #[test]
    fn bug_hunt_variance_rank_n_zero() { // BUG: division by n=0 produces NaN instead of 0.0
        // n=0, p=2
        let v = variance_rank_vec(&[], 0, 2);
        assert_eq!(v.len(), 2);
        // The loop `(0..0).map(...)` produces no iterations, so sum = 0.
        // mean = 0.0 / 0.0 = NaN. var = 0.0/0.0 = NaN.
        // This is a latent bug: NaN propagates through variance computation.
        for &vi in &v {
            // Check if NaN — this is the bug: should be 0.0 for an empty column
            if vi.is_nan() {
                // BUG confirmed: division by n=0 produces NaN
                panic!("BUG: variance_rank_vec with n=0 produces NaN instead of 0.0");
            }
        }
    }

    /// variance_rank_vec with p=0: should return empty vector.
    #[test]
    fn bug_hunt_variance_rank_p_zero() {
        let v = variance_rank_vec(&[], 5, 0);
        assert!(v.is_empty(), "p=0 should produce empty variance vector");
    }

    /// covariance_rank_vec with n=0, p=2: the n < 2 guard returns zeros.
    #[test]
    fn bug_hunt_covariance_rank_n_zero() {
        let v = covariance_rank_vec(&[], 0, 2, &[]);
        assert_eq!(v.len(), 2);
        for &vi in &v {
            assert!(approx_eq(vi, 0.0, 1e-12), "n=0 cov should be 0, got {vi}");
        }
    }

    /// silhouette with empty input: should return empty.
    #[test]
    fn bug_hunt_silhouette_empty() {
        let sv = silhouette_samples_vec(&[], 0, 2, &[]);
        assert!(sv.is_empty(), "empty input should produce empty silhouette");
    }

