    /// Bimodal distribution: should have low W (far from normal).
    #[test]
    fn bug_hunt_shapiro_bimodal() {
        let mut x = Vec::new();
        for _ in 0..20 { x.push(0.0); }
        for _ in 0..20 { x.push(100.0); }
        let w = shapiro_w_scalar(&x);
        assert!(w.is_finite(), "bimodal W should be finite, got {w}");
        assert!(w < 0.9, "bimodal W should be low (<0.9), got {w}");
    }

    /// Exactly 3 elements (minimum): exercises the n > 4 guard (inner loop skipped)
    /// and the n=3 special case where a[2] = a_nm1, a[0] = -a_n, a[1] = -a_nm1.
    #[test]
    fn bug_hunt_shapiro_n3_minimum() { // BUG: W exceeds 1.0 (1.009) for n=3 skewed input
        let x = [1.0, 100.0, 200.0];
        let w = shapiro_w_scalar(&x);
        assert!(w.is_finite() && w >= 0.0 && w <= 1.0,
            "n=3 W should be in [0,1], got {w}");
    }

    /// All negative values: W is shift-invariant, so should be same as
    /// shifted-to-positive version.
    #[test]
    fn bug_hunt_shapiro_all_negative() {
        let x_neg: Vec<f64> = (1..=10).map(|i| -(i as f64)).collect();
        let x_pos: Vec<f64> = (1..=10).map(|i| i as f64).collect();
        let w_neg = shapiro_w_scalar(&x_neg);
        let w_pos = shapiro_w_scalar(&x_pos);
        assert!(
            approx_eq(w_neg, w_pos, 1e-10),
            "W should be shift/reflection invariant: W_neg={w_neg}, W_pos={w_pos}"
        );
    }

    /// W is scale-invariant: multiplying all values by a constant should
    /// not change W.
    #[test]
    fn bug_hunt_shapiro_scale_invariance() {
        let x: Vec<f64> = (1..=20).map(|i| i as f64).collect();
        let x_scaled: Vec<f64> = x.iter().map(|v| v * 1000.0).collect();
        let w = shapiro_w_scalar(&x);
        let w_scaled = shapiro_w_scalar(&x_scaled);
        assert!(
            approx_eq(w, w_scaled, 1e-10),
            "W should be scale-invariant: W={w}, W_scaled={w_scaled}"
        );
    }

    /// W is shift-invariant: adding a constant should not change W.
    #[test]
    fn bug_hunt_shapiro_shift_invariance() {
        let x: Vec<f64> = (1..=20).map(|i| i as f64).collect();
        let x_shifted: Vec<f64> = x.iter().map(|v| v + 1e6).collect();
        let w = shapiro_w_scalar(&x);
        let w_shifted = shapiro_w_scalar(&x_shifted);
        assert!(
            approx_eq(w, w_shifted, 1e-6),
            "W should be shift-invariant: W={w}, W_shifted={w_shifted}"
        );
    }

