    // ─────────────────────────────────────────────────────────────────────────
    // Calinski-Harabasz edge cases
    // ─────────────────────────────────────────────────────────────────────────

    /// Calinski-Harabasz with identical points per cluster (zero within-scatter):
    /// should return Infinity per the implementation.
    #[test]
    fn bug_hunt_calinski_zero_within_scatter() {
        // Two clusters, each with identical points at different locations.
        // Cluster 0: all at (0,0), Cluster 1: all at (10,10)
        let flat = [0.0, 0.0, 0.0, 0.0, 10.0, 10.0, 10.0, 10.0]; // n=4, p=2
        let _labels = [0i64, 0, 1, 1];
        let n = 4;
        let p = 2;
        let _k = 2;

        // Compute CH by hand
        let mut x_bar = vec![0.0; p];
        for j in 0..p {
            let sum: f64 = (0..n).map(|i| flat[i * p + j]).sum();
            x_bar[j] = sum / n as f64; // [5, 5]
        }

        let mut between = 0.0;
        let within = 0.0;
        // Cluster 0: centroid = [0,0], 2 points
        let mu0 = [0.0, 0.0];
        let d2_0: f64 = mu0.iter().zip(x_bar.iter()).map(|(a, b)| (a - b).powi(2)).sum();
        between += 2.0 * d2_0; // 2 * (25 + 25) = 100
        // Within cluster 0: all points at centroid, so 0
        // Cluster 1: centroid = [10,10], 2 points
        let mu1 = [10.0, 10.0];
        let d2_1: f64 = mu1.iter().zip(x_bar.iter()).map(|(a, b)| (a - b).powi(2)).sum();
        between += 2.0 * d2_1; // 2 * (25 + 25) = 100
        // Total between = 200, within = 0
        assert_eq!(within, 0.0);
        let _ = between; // suppress unused warning — we only care that within==0

        // The implementation returns Infinity when within_scatter == 0
        // (verified by reading source line 1012-1013)
    }

    /// Calinski-Harabasz: verify that well-separated clusters produce higher
    /// score than overlapping clusters (basic sanity from source).
    #[test]
    fn bug_hunt_calinski_monotonicity() {
        // Well separated: [0,0],[0,0],[10,10],[10,10]
        let flat_good = [0.0, 0.0, 0.0, 0.0, 10.0, 10.0, 10.0, 10.0];
        let labels = [0i64, 0, 1, 1];
        let n = 4;
        let p = 2;
        let k = 2;

        // CH for well-separated
        let ch_good = compute_ch(&flat_good, n, p, &labels, k);

        // Overlapping: [0,0],[1,1],[0.5,0.5],[1.5,1.5]
        let flat_bad = [0.0, 0.0, 1.0, 1.0, 0.5, 0.5, 1.5, 1.5];
        let ch_bad = compute_ch(&flat_bad, n, p, &labels, k);

        assert!(ch_good > ch_bad,
            "well-separated CH ({ch_good}) should be > overlapping CH ({ch_bad})");
    }

    fn compute_ch(flat: &[f64], n: usize, p: usize, labels: &[i64], k: usize) -> f64 {
        let mut x_bar = vec![0.0; p];
        for j in 0..p {
            let sum: f64 = (0..n).map(|i| flat[i * p + j]).sum();
            x_bar[j] = sum / n as f64;
        }
        let mut unique: Vec<i64> = labels.to_vec();
        unique.sort();
        unique.dedup();
        let label_to_idx: std::collections::HashMap<i64, usize> = unique.iter()
            .enumerate().map(|(idx, &lab)| (lab, idx)).collect();
        let mut members: Vec<Vec<usize>> = vec![vec![]; k];
        for (i, &l) in labels.iter().enumerate() {
            members[label_to_idx[&l]].push(i);
        }
        let mut between = 0.0;
        let mut within = 0.0;
        for ms in &members {
            let nc = ms.len() as f64;
            let mut mu = vec![0.0; p];
            for &i in ms {
                for j in 0..p { mu[j] += flat[i * p + j]; }
            }
            for j in 0..p { mu[j] /= nc; }
            let d2: f64 = mu.iter().zip(x_bar.iter()).map(|(a, b)| (a - b).powi(2)).sum();
            between += nc * d2;
            for &i in ms {
                let d: f64 = (0..p).map(|j| (flat[i * p + j] - mu[j]).powi(2)).sum();
                within += d;
            }
        }
        if within == 0.0 { return f64::INFINITY; }
        (between / (k - 1) as f64) / (within / (n - k) as f64)
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Variance/covariance rank correctness
